tests.source:
fnc s01_struct_extend(): void {
    const base = infer struct{foo: 5};
    const next = infer struct{...base, bar: "foo"};
    return;
}

fnc s02_record_extend(): void {
    const base = infer record{foo: 5};
    const next = record{...base, bar: "foo"};
    return;
}

fnc s03_struct_to_record(): void {
    const base = infer struct{foo: 5};
    const next = record{...base, bar: "foo"};
    return;
}

fnc s04_record_to_struct(): void {
    const base = record{foo: 5};
    const next = infer struct{...base, bar: "foo"};
    return;
}

fnc s05_override_type(): void {
    const base = record{foo: 5};
    const next = record{...base, foo: "retyped"};
    return;
}

fnc s06_multi_spread(): void {
    const a = record{x: 1, y: 2};
    const b = record{y: "two", z: true};
    const next = record{...a, ...b, x: 5};
    return;
}

fnc s07_empty(): void {
    const empty = record{};
    const next = record{...empty, foo: 5};
    return;
}

fnc s08_short_alias(): void {
    const base = infer struct{foo: 5};
    const T2 v = infer struct{...base, bar: "foo"};
    return;
}

fnc s09_record_alias(): void {
    const base = infer struct{foo: 5};
    const T3 w = infer record{...base, bar: "foo"};
    return;
}

fnc e01_duplicate(): void {
    const base = record{foo: 5};
    const next = record{foo: 3, ...base, foo: 4};
    return;
}

fnc e02_nonaggregate(): void {
    const next = record{...42};
    return;
}

fnc e03_unknown(): void {
    const next = infer struct{...absent, bar: 5};
    return;
}

fnc e04_wrong_type(): void {
    const base = record{foo: "wrong"};
    const next = struct{foo: int}{...base};
    return;
}

fnc e05_extra(): void {
    const base = record{foo: 5, bar: true};
    const next = struct{foo: int}{...base};
    return;
}

fnc e06_missing(): void {
    const base = record{foo: 5};
    const next = struct{foo: int, bar: bool}{...base};
    return;
}

fnc e07_unknown_annotation(): void {
    const base = infer struct{foo: 5};
    const UnknownType v = record{...base};
    return;
}

fnc e08_computed(): void {
    const base = record{foo: 5};
    const next = record{...base, `bar`: 2};
    return;
}

fnc e09_borrow(): void {
    let mut int count = 4;
    const base = record{foo: rt mut borrow count};
    const next = record{...base};
    return;
}
